mapper.select:
SELECT m.*
FROM tb_menus m
WHERE m.store_id = #{storeId}
  AND m.category_id = #{categoryId}
  AND m.is_active = TRUE
ORDER BY m.sort_order, m.id

SELECT m.id, m.store_id, m.category_id, m.name, m.description, m.price, m.original_price, m.image_url, m.is_popular, m.is_recommended, m.is_sold_out, m.is_active, m.sort_order, c.name as category_name FROM tb_menus m LEFT JOIN tb_menu_category c ON m.category_id = c.id WHERE m.store_id = #{storeId}
AND m.category_id = #{categoryId}
AND m.is_active = 1 ORDER BY m.sort_order ASC, m.id ASC

mapper.update:
UPDATE tb_menus
SET is_active = #{isActive}, updated_at = NOW()
WHERE id = #{menuId}

UPDATE tb_menus
SET is_sold_out = #{isSoldOut}, updated_at = NOW()
WHERE id = #{menuId}
